output_text:
[
  {
    "id": "must_take_cart_for_shopping_trip",
    "text": "A shopper who starts a trip should obtain a cart before completing the trip, regardless of where the cart station is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper should not leave the store without the cart they used for the trip, independent of the exit's coordinates.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts should not be taken into single-file shelf aisles, defined relationally by opposed shelves and one-cell usable width rather than by fixed locations.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_motion_in_shelf_bottleneck",
    "text": "A shopper should not push a cart through a one-cell-wide passage next to shelves, because such bottlenecks may arise in different orientations or layouts.",
    "abstraction": {
      "state_properties": {
        "shelf_bottleneck": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "MOVE",
          "shelf_bottleneck"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_clearings",
    "text": "If a shopper parks or releases a cart, they should do so only in a wide open area that is not immediately beside a shelf, so the rule follows aisle geometry rather than coordinates.",
    "abstraction": {
      "state_properties": {
        "wide_open_parking_area": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "wide_open_parking_area"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_any_parked_cart",
    "text": "After parking a cart, a shopper should return and pick it up before the trip ends, no matter where the temporary parking place is.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickup_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart",
      "discharge": "pickup_cart"
    }
  },
  {
    "id": "parking_cart_is_for_single_file_aisle_errand",
    "text": "Parking a cart should be followed by a cartless errand into a single-file shelf aisle, capturing the layout-independent purpose of temporarily leaving the cart behind.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "cartless_single_file_shelf_aisle": {
          "and": [
            {
              "not": "hasCart"
            },
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart",
      "discharge": "cartless_single_file_shelf_aisle"
    }
  },
  {
    "id": "cart_required_for_normal_shelf_interaction",
    "text": "Shelf interactions in ordinary non-single-file shelf areas should be done with the cart present, while narrow single-file shelf aisles are treated as the exception.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "ordinary_shelf_area": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "INTERACT",
          "ordinary_shelf_area"
        ]
      }
    }
  }
]
